/**
 * Minimal client interface for ephemeral key derivation.
 *
 * This interface contains only the `getMasterSeed` function, allowing all existing
 * key generators to work with ephemeral seeds. When creating a UTXO with an ephemeral
 * unlocker, an ephemeral seed is derived from the main client's master seed and a
 * generation index. This ephemeral seed can then be used with existing key derivation
 * factories.
 *
 * @remarks
 * ## Why This Interface?
 *
 * The Umbra protocol uses a hierarchical key derivation scheme where all keys
 * (master viewing key, poseidon private key, X25519 key, etc.) are derived from
 * a master seed. For ephemeral unlockers, we derive an "ephemeral master seed"
 * from the main seed and a generation index, then use the same derivation functions.
 *
 * By defining this minimal interface, existing key generators like:
 * - `getMasterViewingKeyDeriver({ client })`
 * - `getPoseidonKeyGenerator({ client })`
 * - `getUserAccountX25519KeypairDeriver({ client })`
 *
 * Can accept either an `IUmbraClient` or an `IEphemeralUmbraClient`, since they
 * only need `client.masterSeed.getMasterSeed()` internally.
 *
 * ## Usage Pattern
 *
 * ```typescript
 * // 1. Derive ephemeral seed from main client and generation index
 * const ephemeralSeed = await deriveEphemeralMasterSeed(
 *   await client.masterSeed.getMasterSeed(),
 *   generationIndex
 * );
 *
 * // 2. Create ephemeral client wrapper
 * const ephemeralClient: IEphemeralUmbraClient = {
 *   getMasterSeed: async () => ephemeralSeed,
 * };
 *
 * // 3. Use existing key generators with ephemeral client
 * const ephemeralMvk = await getMasterViewingKeyDeriver({ client: ephemeralClient })();
 * const ephemeralPk = await getPoseidonKeyGenerator({ client: ephemeralClient })();
 * ```
 *
 * @example
 * ```typescript
 * import { IEphemeralUmbraClient } from '@umbra-privacy/sdk';
 *
 * function createEphemeralClient(ephemeralSeed: MasterSeed): IEphemeralUmbraClient {
 *   return {
 *     getMasterSeed: async () => ephemeralSeed,
 *   };
 * }
 * ```
 *
 * @see {@link IUmbraClient}
 * @see {@link GetMasterSeedFunction}
 * @public
 */
interface IEphemeralUmbraClient {
    /**
     * Function to retrieve the ephemeral master seed.
     *
     * For ephemeral clients, this returns the derived ephemeral seed
     * (not the main client's master seed).
     */
    getMasterSeed: GetMasterSeedFunction;
}
