/**
 * Result for a single encrypted token account balance query.
 *
 * This discriminated union type indicates the state of the token account:
 * - `non_existent`: Account does not exist on-chain
 * - `uninitialized`: Account exists but Arcium balance is not initialized (IS_ARCIUM_BALANCE_INITIALISED = false)
 * - `mxe`: Account is initialized in MXE mode (IS_SHARED_MODE = false), balance cannot be decrypted client-side
 * - `shared`: Account is initialized in shared mode (IS_SHARED_MODE = true), balance is decrypted and returned
 *
 * @remarks
 * ## Status Bits
 *
 * The state is determined by checking the following status bits from the on-chain account:
 * - Bit 4: `IS_ARCIUM_BALANCE_INITIALISED` - Whether the Arcium encrypted balance has been set up
 * - Bit 3: `IS_SHARED_MODE` - TRUE = Shared mode (client can decrypt), FALSE = MXE mode (only MXE can decrypt)
 *
 * @example
 * ```typescript
 * const result: QueryEncryptedBalanceResult = await fetcher([mint]);
 * const mintResult = result.get(mint);
 *
 * switch (mintResult?.state) {
 *     case 'shared':
 *         console.log(`Balance: ${mintResult.balance}`);
 *         break;
 *     case 'mxe':
 *         console.log("Account is in MXE mode, cannot decrypt balance client-side");
 *         break;
 *     case 'uninitialized':
 *         console.log("Account exists but Arcium balance not initialized");
 *         break;
 *     case 'non_existent':
 *         console.log("Token account doesn't exist for this mint");
 *         break;
 * }
 * ```
 *
 * @see {@link QueryEncryptedBalanceFunction}
 * @public
 */
type QueryEncryptedBalanceResult = {
    readonly state: "non_existent";
} | {
    readonly state: "uninitialized";
} | {
    readonly state: "mxe";
} | {
    readonly state: "shared";
    readonly balance: U64;
};
/**
 * Function type for fetching and decrypting encrypted token account balances.
 *
 * This function takes multiple mint addresses and returns a map of decrypted
 * balances for each mint. The function uses the user address from the client
 * to derive the token account PDAs.
 *
 * @param mints - Array of token mint addresses to fetch balances for
 * @returns A Promise resolving to a Map of mint addresses to balance results
 *
 * @remarks
 * ## Implementation Details
 *
 * The function internally:
 * 1. Derives token account PDAs for each mint using the user's address
 * 2. Batch fetches all account data using the AccountInfoProvider
 * 3. Decodes the raw bytes into typed account structures
 * 4. Decrypts the balance using the provided RcDecryptorFunction
 * 5. Returns a map of results for each mint
 *
 * ## PDA Derivation
 *
 * Token account PDAs are derived using the seeds:
 * - `SHA-256("EncryptedTokenAccount")` hash prefix
 * - User's wallet address (32 bytes)
 * - Token mint address (32 bytes)
 *
 * ## Error Handling
 *
 * - Non-existent accounts return `{ state: 'non_existent' }`
 * - Uninitialized accounts return `{ state: 'uninitialized' }`
 * - MXE mode accounts return `{ state: 'mxe' }` (balance cannot be decrypted client-side)
 * - Shared mode accounts return `{ state: 'shared', balance }` with decrypted balance
 * - Decryption errors are thrown as exceptions
 * - RPC errors are thrown as exceptions
 *
 * @example
 * ```typescript
 * import { getQueryEncryptedBalanceFunction } from "@umbra-privacy/sdk";
 * import { address } from "@solana/kit";
 *
 * // Create the fetcher with just the client (uses default dependencies)
 * const fetchBalances = getQueryEncryptedBalanceFunction({ client });
 *
 * // Fetch balances for multiple mints
 * const mints = [
 *     address("EPjFWdd5AufqSSqeM2qN1xzybapC8G4wEGGkZwyTDt1v"), // USDC
 *     address("Es9vMFrzaCERmJfrF4H2FYD4KCoNkY11McCe8BenwNYB"), // USDT
 * ];
 *
 * const balances = await fetchBalances(mints);
 *
 * for (const [mint, result] of balances) {
 *     if (result.state === 'shared') {
 *         console.log(`${mint}: ${result.balance}`);
 *     } else {
 *         console.log(`${mint}: ${result.state}`);
 *     }
 * }
 * ```
 *
 * @see {@link QueryEncryptedBalanceResult}
 * @see {@link GetQueryEncryptedBalanceFunction}
 * @public
 */
type QueryEncryptedBalanceFunction = (mints: readonly Address[]) => Promise<Map<Address, QueryEncryptedBalanceResult>>;
/**
 * Required arguments for creating an encrypted token account balance fetcher.
 *
 * @example
 * ```typescript
 * const args: GetQueryEncryptedBalanceFunctionArgs = {
 *     client: umbraClient,
 * };
 *
 * // Uses default dependencies derived from the client
 * const fetcher = getQueryEncryptedBalanceFunction(args);
 * ```
 *
 * @see {@link GetQueryEncryptedBalanceFunction}
 * @public
 */
