/**
 * Interface for the ClaimReceiverClaimableUtxoIntoEta ZK prover.
 *
 * @remarks
 * This interface defines the contract for zero-knowledge proof generation
 * for the ClaimDepositIntoConfidentialAmount circuit when claiming UTXOs
 * that were deposited by others for this receiver (receiver-claim flow).
 *
 * **Circuit Purpose:**
 * Claims one or more deposit UTXOs sent to this receiver and combines them
 * into a single confidential balance output. Uses the receiver's registered
 * user commitment (from their EncryptedUserAccount) to prove ownership.
 *
 * **Key Differences from Ephemeral Unlocker Claim:**
 * - Supports multiple leaves (up to 4) in a single proof
 * - Uses the receiver's actual registered user commitment (not ephemeral)
 * - Multiple UTXO burner transactions needed for > 2 nullifiers
 *
 * **Key Operations:**
 * 1. Reconstruct H1 and H2 for each leaf (up to 4)
 * 2. Verify Merkle paths to root for all leaves
 * 3. Sum amounts across all leaves and calculate fees
 * 4. Evaluate polynomial commitment
 * 5. Generate rescue encryptions and commitment
 * 6. Compute aggregated hash
 *
 * @public
 */
/**
 * Valid batch sizes for claiming UTXOs (1-4).
 * Each batch size corresponds to a different ZK circuit.
 *
 * @see {@link IZkProverForClaimReceiverClaimableUtxoIntoEncryptedBalance}
 * @public
 */
type ClaimBatchSize = 1 | 2 | 3 | 4;
/**
 * ZK prover interface for claiming UTXOs with receiver unlocker into an Encrypted Token Account.
 *
 * @remarks
 * There are 4 different ZK circuits (one per batch size 1-4). The `prove` method
 * receives all circuit inputs and an `nLeaves` parameter indicating which circuit to use.
 *
 * @see {@link ClaimBatchSize}
 * @see {@link ClaimReceiverClaimableUtxoIntoEncryptedBalanceCircuitInputs}
 * @public
 */
interface IZkProverForClaimReceiverClaimableUtxoIntoEncryptedBalance {
    /**
     * Generates a Groth16 proof for claiming UTXOs with receiver unlocker into ETA.
     *
     * @remarks
     * **IMPORTANT: Circuit Selection by Batch Size**
     *
     * There are 4 different ZK circuits for claiming UTXOs, one for each batch
     * size (1-4 UTXOs). Each circuit has different:
     * - Proving key (zkey file)
     * - Verifying key
     * - Circuit constraints
     *
     * The `nLeaves` parameter determines which circuit to use. The prover
     * implementation must:
     * 1. Load the appropriate proving key for the given batch size
     * 2. Generate a proof using that specific circuit
     * 3. Return the proof compatible with the on-chain verifier for that size
     *
     * **Example Implementation:**
     * ```typescript
     * class ClaimProver implements IZkProverForClaimReceiverClaimableUtxoIntoEncryptedBalance {
     *     private zkeyPaths: Record<ClaimBatchSize, string>;
     *     private wasmPaths: Record<ClaimBatchSize, string>;
     *
     *     async prove(inputs, nLeaves) {
     *         const zkeyPath = this.zkeyPaths[nLeaves];
     *         const wasmPath = this.wasmPaths[nLeaves];
     *         // Use snarkjs or similar to generate proof
     *         return await snarkjs.groth16.fullProve(inputs, wasmPath, zkeyPath);
     *     }
     * }
     * ```
     *
     * **Performance:**
     * Proof generation is computationally intensive. Larger batch sizes take
     * longer due to more constraints. Expect:
     * - 1 UTXO: ~5-10 seconds
     * - 4 UTXOs: ~20-40 seconds
     * (Hardware dependent)
     *
     * @param inputs - All inputs required for the circuit (including inverses)
     * @param nLeaves - Number of UTXOs being claimed (1-4), determines which circuit to use
     * @returns A Promise resolving to the three Groth16 proof components
     *
     * @throws If any input value is invalid
     * @throws If nLeaves is not 1-4
     * @throws If inputs don't match the expected size for nLeaves
     * @throws If Merkle verification fails for any leaf
     * @throws If fee calculations are invalid
     * @throws If proof generation fails for any reason
     */
    prove: (inputs: ClaimReceiverClaimableUtxoIntoEncryptedBalanceCircuitInputs, nLeaves: ClaimBatchSize) => Promise<{
        /** The A component of the Groth16 proof (G1 point) */
        readonly proofA: Groth16ProofA;
        /** The B component of the Groth16 proof (G2 point) */
        readonly proofB: Groth16ProofB;
        /** The C component of the Groth16 proof (G1 point) */
        readonly proofC: Groth16ProofC;
    }>;
}
